def _combine_mysql_datetime(date_value, time_value):
    """Ενώνει DATE/TIME της MySQL, είτε το TIME επιστρέφεται ως timedelta είτε ως time."""
    if isinstance(time_value, datetime.timedelta):
        seconds = int(time_value.total_seconds()) % (24 * 60 * 60)
        time_value = (datetime.datetime.min + datetime.timedelta(seconds=seconds)).time()
    elif not isinstance(time_value, datetime.time):
        time_text = str(time_value).split('.')[0]
        time_value = datetime.datetime.strptime(time_text, "%H:%M:%S").time()
    return datetime.datetime.combine(date_value, time_value)


def _mysql_time_to_timedelta(value):
    """Μετατρέπει MySQL TIME σε timedelta, ακόμη και για διάρκεια >24 ωρών."""
    if isinstance(value, datetime.timedelta):
        return value
    if isinstance(value, datetime.time):
        return datetime.timedelta(hours=value.hour, minutes=value.minute,
                                  seconds=value.second, microseconds=value.microsecond)
    text_value = str(value).strip()
    sign = -1 if text_value.startswith("-") else 1
    if text_value[:1] in ("-", "+"):
        text_value = text_value[1:]
    main_part = text_value.split(".")[0]
    parts = main_part.split(":")
    if len(parts) != 3:
        raise ValueError("Μη έγκυρη τιμή TIME: " + str(value))
    hours, minutes, seconds = (int(part) for part in parts)
    return sign * datetime.timedelta(hours=hours, minutes=minutes, seconds=seconds)


def _calculate_parking_cost(duration, tariff_rows):
    """Εφαρμόζει μία φορά τις υπάρχουσες φάσεις χρέωσης στην προς χρέωση διάρκεια."""
    if duration <= datetime.timedelta(0) or not tariff_rows:
        return 0.0

    rows = list(tariff_rows)
    threshold = _mysql_time_to_timedelta(rows[0][1])
    remaining = duration
    total = 0.0

    for row in rows:
        if remaining <= threshold:
            break
        phase_duration = _mysql_time_to_timedelta(row[1])
        total += float(row[2])
        remaining -= phase_duration

    last_duration = _mysql_time_to_timedelta(rows[-1][1])
    last_cost = float(rows[-1][2])
    while remaining > threshold and last_duration > datetime.timedelta(0):
        total += last_cost
        remaining -= last_duration

    return total


def _covered_subscription_duration(parking_start, parking_end, subscription_rows):
    """Επιστρέφει τη συνολική (χωρίς διπλομέτρηση) κάλυψη συνδρομών μέσα στη στάθμευση."""
    if parking_end <= parking_start:
        return datetime.timedelta(0)

    intervals = []
    for row in subscription_rows:
        try:
            sub_start = _combine_mysql_datetime(row[0], row[1])
            sub_end = _combine_mysql_datetime(row[2], row[3])
        except (TypeError, ValueError):
            continue
        overlap_start = max(parking_start, sub_start)
        overlap_end = min(parking_end, sub_end)
        if overlap_end > overlap_start:
            intervals.append((overlap_start, overlap_end))

    if not intervals:
        return datetime.timedelta(0)

    intervals.sort(key=lambda item: item[0])
    merged_start, merged_end = intervals[0]
    covered = datetime.timedelta(0)
    for current_start, current_end in intervals[1:]:
        if current_start <= merged_end:
            if current_end > merged_end:
                merged_end = current_end
        else:
            covered += merged_end - merged_start
            merged_start, merged_end = current_start, current_end
    covered += merged_end - merged_start
    return covered


try:
    from lytrax_afm import validate_afm
except ImportError:
    def validate_afm(value):
        """Έλεγχος ελληνικού ΑΦΜ (9 ψηφία) όταν δεν είναι εγκατεστημένο το lytrax_afm."""
        afm_value = str(value).strip()
        if len(afm_value) != 9 or not afm_value.isdigit():
            return False
        checksum = sum(int(afm_value[i]) * (2 ** (8 - i)) for i in range(8))
        return (checksum % 11) % 10 == int(afm_value[8])


