        # Η είσοδος MySQL γίνεται μία φορά στην αρχή, χωρίς αποθηκευμένο password.
        users, passwords = mysql_login.get_session()
        hosts = mysql_login.MYSQL_HOST
        base = mysql_login.MYSQL_DATABASE
        global threadmemory
        global renameplaces
        global countidbase
        global inputs
