        # Σύνδεση SQL
        # Οι συναρτήσεις έχουν διαχωριστεί ανά λειτουργία στα parking_modules.
        # Επανασύνδεση των globals με το αρχικό module για πλήρη συμβατότητα
        # με την υφιστάμενη MySQL κατάσταση και τα GUI callbacks.
        _handlers = {}
        for _module in (
            parking_system,
            parking_entrance,
            parking_departure,
            parking_subscriptions,
            parking_pricing,
            parking_directory,
            parking_reports,
        ):
            for _name, _callback in _module.create_handlers(self, top, _handlers).items():
                _handlers[_name] = types.FunctionType(
                    _callback.__code__, globals(), _callback.__name__,
                    _callback.__defaults__, _callback.__closure__
                )
        # Αποκατάσταση closure αναφορών (αλληλοκλήσεις και clock loop).
        for _fn in _handlers.values():
            for _free_name, _cell in zip(_fn.__code__.co_freevars, _fn.__closure__ or ()):
                if _free_name in _handlers:
                    _cell.cell_contents = _handlers[_free_name]
        # Το υπάρχον Tkinter wiring χρησιμοποιεί τα ίδια ονόματα callbacks.
        msqlconnect = _handlers['msqlconnect']
        buttonexit = _handlers['buttonexit']
        saveandprint = _handlers['saveandprint']
